import logging
from ta_moler.device.nokia_proxy_pc import NokiaProxyPc
from moler.helpers import call_base_class_method_with_same_name, mark_to_call_base_class_method_with_same_name


@call_base_class_method_with_same_name
class FzmConsole(NokiaProxyPc):
    r"""
    Fzmconsole device class.

    Example of device in yaml configuration file:
    - with PROXY_PC:
      ENB1:
       DEVICE_CLASS: ta_moler.device.fzm_console.FzmConsole
       CONNECTION_HOPS:
         UNIX_LOCAL:
           PROXY_PC:
             execute_command: ssh # default value
             command_params:
               expected_prompt: proxy_pc_prompt
               host: host_ip
               login: login
               password: password
         LINUX:
           PROXY_PC:
             execute_command: exit # default value
             command_params:
               expected_prompt: proxy_pc_prompt
    - without PROXY_PC:
      ENB1:
       DEVICE_CLASS: ta_moler.device.fzm_console.FzmConsole
       CONNECTION_HOPS:
         UNIX_LOCAL:
           LINUX:
             execute_command: telnet # default value
             command_params:
               host: tty_server_host
               port: tty_port
    """

    linux = "LINUX"
    aashell = "AASHELL"
    argon = "ARGON"

    def __init__(self, sm_params, name=None, io_connection=None, io_type=None, variant=None, io_constructor_kwargs=None,
                 initial_state=None, lazy_cmds_events=False):
        """
        Create unix device communicating over io_connection.

        :param io_connection: External-IO connection having embedded moler-connection
        :param io_type: External-IO connection connection type
        :param variant: External-IO connection variant
        :param io_constructor_kwargs: additional parameter into constructor of selected connection type
                        (if not given then default one is taken)
        :param initial_state: Initial state for device
        :param lazy_cmds_events: set False to load all commands and events when device is initialized, set True to load
                        commands and events when they are required for the first time.
        """
        sm_params = sm_params.copy()
        initial_state = initial_state if initial_state is not None else FzmConsole.linux
        super(FzmConsole, self).__init__(sm_params=sm_params, name=name, io_connection=io_connection, io_type=io_type,
                                         variant=variant, io_constructor_kwargs=io_constructor_kwargs,
                                         initial_state=initial_state, lazy_cmds_events=lazy_cmds_events)
        self.logger = logging.getLogger('moler.fzm_console')

    def goto_state(self, state, timeout=-1, rerun=5, send_enter_after_changed_state=False,
                   log_stacktrace_on_fail=True, keep_state=False, timeout_multiply=1.0,
                   sleep_after_changed_state=0.5):
        """
        Go to given state by FZM.

        :param state: Name of state to go.
        :param timeout: Timeout for going up. If -1 then only commands timeout are important.
        :param rerun: How many times try to change state if it fails. Set 0 to no rerun.
        :param send_enter_after_changed_state: Set True to send enter after change state.
        :param log_stacktrace_on_fail: Set True to log stacktrace on fail.
        :param keep_state: if True and state is changed without goto_state then device tries to change state to state
        defined by goto_state.
        :param timeout_multiply: how many times multiply passed timeout to get final timeout.
        :return: None
        :raise: DeviceChangeStateFailure if device was not able to go to state.
        """
        return super(FzmConsole, self).goto_state(state=state, timeout=timeout, rerun=rerun,
                                                  send_enter_after_changed_state=send_enter_after_changed_state,
                                                  log_stacktrace_on_fail=log_stacktrace_on_fail, keep_state=keep_state,
                                                  timeout_multiply=timeout_multiply,
                                                  sleep_after_changed_state=sleep_after_changed_state
                                                  )

